# Checks the 35-type recursion (Lean `step`, `lv0`) against Hardin's b-file for A246737.
# Usage: curl -sO https://oeis.org/A246737/b246737.txt && python3 check_bfile.py
b=[int(l.split()[1]) for l in open('b246737.txt') if l.strip() and not l.startswith('#')]
pos=[];d=1
while len(pos)<len(b):
    for n in range(1,d+1): pos.append((n,d+1-n))
    d+=1
def step(s,k,e):
    return [(1)*s[0] + (-e + k - 1)*s[1] + (e)*s[2], (1)*s[3] + (1)*s[5] + (-e + k - 3)*s[6] + (e)*s[8], (1)*s[4] + (-e + k - 1)*s[7], (1)*s[9] + (1)*s[11] + (-e + k - 3)*s[12] + (e)*s[14], (1)*s[10] + (-e + k - 1)*s[13], (1)*s[15] + (1)*s[16] + (-e + k - 3)*s[18] + (e)*s[20], (1)*s[21] + (1)*s[24] + (1)*s[27] + (-e + k - 5)*s[30] + (e)*s[34], (1)*s[22] + (1)*s[29] + (-e + k - 3)*s[32], (1)*s[23] + (1)*s[26] + (-e + k - 3)*s[33], (1)*s[15] + (1)*s[16] + (-e + k - 3)*s[18] + (e)*s[20], (1)*s[17] + (-e + k - 1)*s[19], (1)*s[9] + (1)*s[11] + (-e + k - 3)*s[12] + (e)*s[14], (1)*s[21] + (1)*s[24] + (1)*s[27] + (-e + k - 5)*s[30] + (e)*s[34], (1)*s[25] + (1)*s[28] + (-e + k - 3)*s[31], (1)*s[23] + (1)*s[26] + (-e + k - 3)*s[33], (1)*s[3] + (1)*s[5] + (-e + k - 3)*s[6] + (e)*s[8], (1)*s[0] + (-e + k - 2)*s[1] + (e)*s[2], (1)*s[0] + (-e + k - 1)*s[1] + (e - 1)*s[2], (1)*s[3] + (1)*s[5] + (-e + k - 4)*s[6] + (e)*s[8], (1)*s[3] + (1)*s[5] + (-e + k - 3)*s[6] + (e - 1)*s[8], (1)*s[4] + (-e + k - 2)*s[7], (1)*s[21] + (1)*s[24] + (1)*s[27] + (-e + k - 5)*s[30] + (e)*s[34], (1)*s[25] + (1)*s[28] + (-e + k - 3)*s[31], (1)*s[22] + (1)*s[29] + (-e + k - 3)*s[32], (1)*s[9] + (1)*s[11] + (-e + k - 4)*s[12] + (e)*s[14], (1)*s[9] + (1)*s[11] + (-e + k - 3)*s[12] + (e - 1)*s[14], (1)*s[10] + (-e + k - 2)*s[13], (1)*s[15] + (1)*s[16] + (-e + k - 4)*s[18] + (e)*s[20], (1)*s[15] + (1)*s[16] + (-e + k - 3)*s[18] + (e - 1)*s[20], (1)*s[17] + (-e + k - 2)*s[19], (1)*s[21] + (1)*s[24] + (1)*s[27] + (-e + k - 6)*s[30] + (e)*s[34], (1)*s[21] + (1)*s[24] + (1)*s[27] + (-e + k - 5)*s[30] + (e - 1)*s[34], (1)*s[25] + (1)*s[28] + (-e + k - 4)*s[31], (1)*s[22] + (1)*s[29] + (-e + k - 4)*s[32], (1)*s[23] + (1)*s[26] + (-e + k - 4)*s[33]]
def lv0(s,k,e):
    return (-e + k + 1)*s[0] + (e**2 - 2*e*k + k**2 - 1)*s[1] + (-e**2 + e*k + e)*s[2] + (e**2 - 2*e*k + k**2 - 1)*s[3] + (-e**2 + e*k + e)*s[4] + (e**2 - 2*e*k + k**2 - 1)*s[5] + (-e**3 + 3*e**2*k - 3*e**2 - 3*e*k**2 + 6*e*k + e + k**3 - 3*k**2 - k + 3)*s[6] + (e**3 - 2*e**2*k + e*k**2 - e)*s[7] + (e**3 - 2*e**2*k + e*k**2 - e)*s[8] + (e**2 - 2*e*k + k**2 - 1)*s[9] + (-e**2 + e*k + e)*s[10] + (e**2 - 2*e*k + k**2 - 1)*s[11] + (-e**3 + 3*e**2*k - 3*e**2 - 3*e*k**2 + 6*e*k + e + k**3 - 3*k**2 - k + 3)*s[12] + (e**3 - 2*e**2*k + e*k**2 - e)*s[13] + (e**3 - 2*e**2*k + e*k**2 - e)*s[14] + (e**2 - 2*e*k + k**2 - 1)*s[15] + (e**2 - 2*e*k + k**2 - 1)*s[16] + (-e**2 + e*k + e)*s[17] + (-e**3 + 3*e**2*k - 3*e**2 - 3*e*k**2 + 6*e*k + e + k**3 - 3*k**2 - k + 3)*s[18] + (e**3 - 2*e**2*k + e*k**2 - e)*s[19] + (e**3 - 2*e**2*k + e*k**2 - e)*s[20] + (-e**3 + 3*e**2*k - 3*e**2 - 3*e*k**2 + 6*e*k + e + k**3 - 3*k**2 - k + 3)*s[21] + (e**3 - 2*e**2*k + e*k**2 - e)*s[22] + (e**3 - 2*e**2*k + e*k**2 - e)*s[23] + (-e**3 + 3*e**2*k - 3*e**2 - 3*e*k**2 + 6*e*k + e + k**3 - 3*k**2 - k + 3)*s[24] + (e**3 - 2*e**2*k + e*k**2 - e)*s[25] + (e**3 - 2*e**2*k + e*k**2 - e)*s[26] + (-e**3 + 3*e**2*k - 3*e**2 - 3*e*k**2 + 6*e*k + e + k**3 - 3*k**2 - k + 3)*s[27] + (e**3 - 2*e**2*k + e*k**2 - e)*s[28] + (e**3 - 2*e**2*k + e*k**2 - e)*s[29] + (e**4 - 4*e**3*k + 8*e**3 + 6*e**2*k**2 - 24*e**2*k + 14*e**2 - 4*e*k**3 + 24*e*k**2 - 28*e*k - 8*e + k**4 - 8*k**3 + 14*k**2 + 8*k - 15)*s[30] + (-e**4 + 3*e**3*k - 3*e**3 - 3*e**2*k**2 + 6*e**2*k + e**2 + e*k**3 - 3*e*k**2 - e*k + 3*e)*s[31] + (-e**4 + 3*e**3*k - 3*e**3 - 3*e**2*k**2 + 6*e**2*k + e**2 + e*k**3 - 3*e*k**2 - e*k + 3*e)*s[32] + (-e**4 + 3*e**3*k - 3*e**3 - 3*e**2*k**2 + 6*e**2*k + e**2 + e*k**3 - 3*e*k**2 - e*k + 3*e)*s[33] + (-e**4 + 3*e**3*k - 3*e**3 - 3*e**2*k**2 + 6*e**2*k + e**2 + e*k**3 - 3*e*k**2 - e*k + 3*e)*s[34]
def T(n,k):
    e=1 if k%2==0 else 0; s=[1]*35
    for _ in range(n): s=step(s,k,e)
    return lv0(s,k,e)
bad=[(n,k) for (n,k),x in zip(pos,b) if T(n,k)!=x]
print(len(b),'terms checked; mismatches:',len(bad),bad[:10])
